from datetime import datetime, timedelta

BLOCK_TITLES=['준비와 완성 예시','가상 행정사업과 지표','요청문과 사용량','보고서 구조와 근거','보고서 생성 실습','보고서 수치와 요청 검수','기획과 회의록','기획서 생성 실습','첫 휴식','대안과 예산 검토','WBS 실습','Gantt와 선행작업','오류 문서 검수','최종본과 안내메일','저장과 재사용','강사 데스크톱 활용 사례','휴식과 선택 Q&A','휴식과 선택 Q&A 마무리']
BLOCKS=[]
cursor=datetime(2026,10,13,14,0)
for i,title in enumerate(BLOCK_TITLES,1):
    end=cursor+timedelta(minutes=10)
    BLOCKS.append(dict(key=f'b{i:02d}',title=title,start=cursor.strftime('%H:%M'),end=end.strftime('%H:%M'),minutes=10,kind='break' if i==9 else 'qna' if i>=17 else 'demo' if i==16 else 'lecture'))
    cursor=end
SLIDES=[]
SOURCES={'usage':'https://support.claude.com/en/articles/11647753-how-do-usage-and-length-limits-work','desktop':'https://code.claude.com/docs/en/desktop-quickstart','codex':'https://learn.chatgpt.com/docs/app','plans':'https://learn.chatgpt.com/docs/pricing'}

def add(block,type,title,facilitate='',check='',source='',**content):
    b=BLOCKS[block-1]
    first=not any(s['block']==b['key'] for s in SLIDES)
    note=f"운영 구간: {b['start']}-{b['end']} / 10분 블록 / {b['title']}\n이 블록의 장표가 같은 시간을 공유한다. 장표마다 10분을 추가 배정하지 않는다.\n진행: {facilitate}\n완료 확인: {check}\n실패 동선: AI 한도나 접속 장애가 있으면 핵심 사실과 참고답안으로 같은 결과를 완성한다."
    note+=f'\n출처(2026-10-12 확인): {source}' if source else '\n자료: 교육용 가상 행정사업. 수치·기록은 합성 원자료의 집계 또는 명시한 가정이다.'
    SLIDES.append(dict(type=type,title=title,minutes=10 if first else 0,time_start=b['start'],time_end=b['end'],block=b['key'],note=note,**content))

