add(10,'prompt','대안 비교 보완',text='기획서의 대안 A와 B를 비교해 주세요.\n준비 부담, 저장, 검수, 사용량 측면으로 씁니다.\n기본 시험에 A를 고른 이유를 설명합니다.\nB는 강사 시연에서 관찰할 내용으로 남깁니다.\n추가 비용이나 채용을 임의로 만들지 않습니다.',check='대안 선택 이유 완성')

add(11,'statement','WBS 업무 분해',lead='업무마다 담당과 완료 기준',caption='24개 업무를 착수, 시범, 확대, 마무리로 나눕니다.\n일정표를 만들기 전에 선행관계부터 확인합니다.',check='WBS 행의 의미 이해')
add(11,'table','WBS의 핵심 필드',headers=['필드','예시','확인 질문'],rows=[['업무ID','T08','중복 없이 연결되는가'],['담당 역할','행정지원팀','누가 책임지는가'],['선행ID','T07','어떤 작업 뒤에 시작하는가'],['날짜','10/27-10/27','선행 종료 뒤인가'],['완료 기준','수료·취업·예산 재계산','무엇으로 완료를 판단하는가']],caption='전체 24행은 data/wbs.csv와 admin-workbook.xlsx에 있습니다.',check='대표 업무의 필드 확인')
add(11,'prompt','실습 3 WBS 검토',lead='03-wbs-to-paste.txt와 실습 3 요청문을 함께 넣습니다.',text='제공된 원본 WBS 24행을 검토해 주세요.\n업무ID, 담당, 선행ID, 시작일, 종료일, 완료 기준.\n원본 날짜를 유지하고 변경안은 별도로 씁니다.\n담당 누락, 모호한 완료 기준, 중복 ID를 찾습니다.\nT08 지연의 영향을 의존 경로별로 검토합니다.\n확인할 질문과 수정 대안을 표로 남깁니다.',source_file='02-prompts.txt / 실습 3 + 03-wbs-to-paste.txt',check='WBS 검토 메모 저장')

add(12,'gantt','4주 예정 Gantt',headers=['업무 묶음','10/19','10/26','11/02','11/09'],rows=[['범위·지표·서식','예정','','',''],['보고서·수치 검수','','예정','',''],['두 번째 사례 적용','','','예정',''],['측정·서식 보완','','','예정',''],['결과·예산·지속 검토','','','','예정'],['최종 승인·보관','','','','예정']],caption='교육용 가정 일정. 실제 진행률과 완료 성과를 의미하지 않습니다.',check='예정 구간 관계 이해')
add(12,'prompt','일정 지연 상황',text='T08 종료가 10월 30일로 지연됩니다.\nT10의 원래 시작은 10월 28일입니다.\n선행 종료 다음 날 이후 시작 규칙으로 검토합니다.\n직접 충돌과 후속 의존 경로를 구분합니다.\n원본 날짜, 영향, 변경 제안, 승인 필요를 표로 씁니다.\n모든 업무를 일괄 같은 기간만큼 늦추지 않습니다.',check='T10 충돌과 독립 작업 구분')
add(12,'image','WBS와 Gantt의 연결',path='previews/gantt-final.png',caption='WBS 날짜를 바꾸면 예정 구간이 함께 바뀝니다.\n무료 웹에서는 날짜와 영향 검토 메모로 완료할 수 있습니다.',source_file='data/admin-workbook.xlsx / 일정 시트',facilitate='워크북 업로드나 수식 수정은 필수가 아니다.',check='일정 검토 메모 저장')

add(13,'document','실습 4 오류 문서',label='의도적 오류',doc='상담 720명의 참여자에게 서비스를 제공했다.\n취업률은 등록자 대비 37.5%이다.\nAI 도입으로 취업 성과가 20% 증가했다.\n설문에는 수료자 전원이 응답했다.\n잔액은 6,540,000원이며 유료 AI에 배정했다.\n목표 20% 시간절감은 이미 달성했다.',source_file='04-review-to-paste.txt / source/05-review-target.pdf',check='전체 오류 문서에서 오류 최소 8개와 근거 대응')
add(13,'prompt','최종 검수 요청문',text='초안을 사실 묶음과 대조해 주세요.\n사실·계산·분모 오류와 미승인 목표를 구분합니다.\n원문, 정확한 수치나 상태, 출처, 수정 이유를 씁니다.\n없는 원인과 승인 결과는 확인 필요로 남깁니다.\n검수표를 반영한 최종본은 700자 이내로 씁니다.\n확인한 숫자 3개와 남은 질문 1개를 덧붙입니다.',source_file='02-prompts.txt / 실습 4',check='검수표와 수정본 저장')
add(13,'table','오류와 근거 대응 예시',headers=['주장','검수 결과','근거'],rows=[['720명 상담','720건, 중복 포함','상담 기록'],['등록 대비 37.5%','수료 대비 37.5%','등록 원장'],['잔액 6,540,000','5,640,000원','집행 원장'],['시간절감 이미 달성','승인 전 목표','기획 초안']],caption='수치를 고쳐도 원인·승인·성과의 근거가 자동으로 생기지 않습니다.',check='수치 오류와 논리 오류 구분')

add(14,'bullets','최종본 완료 기준',lead='작성 뒤에 사람이 확인할 항목',items=['기간, 단위, 분모를 원자료와 대조합니다.','원인, 목표, 승인 상태를 사실과 구분합니다.','담당과 완료 기준을 넣고 검수 기록을 저장합니다.'],check='보고서와 기획서 최종 저장')
add(14,'document','담당 팀 안내메일 예시',doc='제목: 문서 개선 시험안 검토 요청\n\n담당 팀 여러분, 4주 시험안을 공유합니다.\n기간과 업무시간은 승인 전 가정입니다.\n담당 역할, 완료 기준, 지표 정의를 확인하고\n조정할 사항을 알려주시기 바랍니다.\n실제 적용은 범위와 업무시간 승인 후 결정하겠습니다.',label='교육용 초안',check='승인 확정 안내로 쓰지 않음')
